  test('AC-4: has exactly 19 elements with correct values', () => {
    const expected = [
      'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
      'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
      'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
    ]
    assert.deepEqual(RATING_SCALE, expected)
    assert.equal(RATING_SCALE.length, 19)
    assert.equal(RATING_SCALE[0], 'AAA')
    assert.equal(RATING_SCALE[18], 'CCC-')
  })

  test('AC-5: RATING_SCALE is frozen', () => {
    assert.equal(Object.isFrozen(RATING_SCALE), true)
  })

  test('AC-5: frozen array throws TypeError on push', () => {
    assert.throws(
      () => RATING_SCALE.push('D'),
      TypeError
    )
  })

  test('AC-5: frozen array throws TypeError on element assignment', () => {
    assert.throws(
      () => { RATING_SCALE[0] = 'X' },
