    )
  })

  test('AC-5: RATING_SCALE remains unchanged after mutation attempts', () => {
    const expected = [
      'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
      'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
      'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
    ]
    assert.deepEqual(RATING_SCALE, expected)
    assert.equal(RATING_SCALE.length, 19)
    assert.equal(RATING_SCALE[0], 'AAA')
  })
})

describe('notchChange', () => {
  describe('AC-1, AC-2: basic downgrade/upgrade', () => {
    test('AC-1: downgrade BBB+ to BB+ returns 3', () => {
      const result = notchChange('BBB+', 'BB+')
      assert.equal(result, 3)
      assert.equal(typeof result, 'number')
    })

    test('AC-2: upgrade BB+ to BBB+ returns -3', () => {
      const result = notchChange('BB+', 'BBB+')
      assert.equal(result, -3)
    })
  })

  describe('AC-3: unchanged returns positive 0 (not -0)', () => {
    test('same rating returns 0 for A', () => {
      const result = notchChange('A', 'A')
      assert.equal(Object.is(result, 0), true)
      assert.equal(result, 0)
    })

    test('same rating returns 0 for CCC-', () => {
      const result = notchChange('CCC-', 'CCC-')
      assert.equal(Object.is(result, 0), true)
    })

    test('all ratings return 0 when unchanged', () => {
      for (const rating of RATING_SCALE) {
        const result = notchChange(rating, rating)
        assert.equal(Object.is(result, 0), true, `failed for ${rating}`)
      }
    })
  })

  describe('AC-6: adjacent pairs and matrix', () => {
    test('every adjacent pair forward returns 1', () => {
      for (let i = 0; i < RATING_SCALE.length - 1; i++) {
        const result = notchChange(RATING_SCALE[i], RATING_SCALE[i + 1])
        assert.equal(result, 1, `failed for (${RATING_SCALE[i]}, ${RATING_SCALE[i + 1]})`)
      }
    })

    test('every adjacent pair backward returns -1', () => {
      for (let i = 1; i < RATING_SCALE.length; i++) {
        const result = notchChange(RATING_SCALE[i], RATING_SCALE[i - 1])
        assert.equal(result, -1, `failed for (${RATING_SCALE[i]}, ${RATING_SCALE[i - 1]})`)
      }
    })

    test('AC-6 spot checks', () => {
      assert.equal(notchChange('AAA', 'AA+'), 1)
      assert.equal(notchChange('BBB', 'BBB-'), -1)
      assert.equal(notchChange('BBB-', 'BBB'), 1)
      assert.equal(notchChange('BBB-', 'BB+'), 1)
      assert.equal(notchChange('B-', 'CCC+'), 1)
    })

    test('AC-6 extremes', () => {
      assert.equal(notchChange('AAA', 'CCC-'), 18)
      assert.equal(notchChange('CCC-', 'AAA'), -18)
    })

    test('AC-6 full 19x19 matrix: result equals j - i', () => {
      for (let i = 0; i < RATING_SCALE.length; i++) {
        for (let j = 0; j < RATING_SCALE.length; j++) {
          const result = notchChange(RATING_SCALE[i], RATING_SCALE[j])
          const expected = j - i
          assert.equal(result, expected, `failed for (${i}, ${j}): ${RATING_SCALE[i]} -> ${RATING_SCALE[j]}`)
        }
      }
    })
  })

  describe('AC-7: whitespace handling', () => {
    test('leading and trailing spaces', () => {
      assert.equal(notchChange('  BBB+ ', 'BB+'), 3)
    })

    test('tabs and newlines', () => {
      assert.equal(notchChange('\tA-\n', 'A-'), 0)
    })

    test('leading space with zero-width space', () => {
      assert.equal(notchChange(' AAA', 'AA+​'), 1)
    })

    test('trailing spaces and carriage return', () => {
      assert.equal(notchChange('BB+', ' BBB+\r\n'), -3)
    })
  })

  describe('AC-8: case insensitivity', () => {
    test('lowercase', () => {
      assert.equal(notchChange('bbb+', 'bb+'), 3)
    })

    test('mixed case', () => {
      assert.equal(notchChange('Bb+', 'bBb+'), -3)
    })

    test('all lowercase to uppercase extreme', () => {
      assert.equal(notchChange('aaa', 'CCC-'), 18)
    })

    test('lowercase with spaces to uppercase with spaces', () => {
      assert.equal(notchChange(' ccc- ', 'aAa'), -18)
    })

    test('single letter case variations', () => {
      assert.equal(notchChange('a', 'A'), 0)
    })
  })

  describe('AC-9: invalid rating strings throw RangeError', () => {
    const invalidRatings = [
      'D', 'CC', 'C', 'SD', 'NR', 'WD', 'AAA+', 'CCC--',
      'BBB +', 'BBB+.', 'A−', 'Baa1'
    ]

    test('invalid as previous (with current A)', () => {
      for (const invalid of invalidRatings) {
        assert.throws(
          () => notchChange(invalid, 'A'),
          RangeError,
          `failed for ${invalid}`
        )
      }
    })

    test('invalid as current (with previous A)', () => {
      for (const invalid of invalidRatings) {
        assert.throws(
          () => notchChange('A', invalid),
          RangeError,
          `failed for ${invalid}`
        )
      }
    })
  })

  describe('AC-10: empty/whitespace-only strings throw RangeError', () => {
    const whitespaceOnly = ['', '   ', '\t\n', ' ']

    test('whitespace-only as previous', () => {
      for (const ws of whitespaceOnly) {
        assert.throws(
          () => notchChange(ws, 'A'),
          RangeError,
          `failed for ${JSON.stringify(ws)}`
        )
      }
    })

    test('whitespace-only as current', () => {
      for (const ws of whitespaceOnly) {
        assert.throws(
          () => notchChange('A', ws),
          RangeError,
          `failed for ${JSON.stringify(ws)}`
        )
      }
    })
  })

  describe('AC-11: non-strings throw RangeError (not TypeError)', () => {
    const nonStrings = [
      undefined, null, 3, NaN, true, {}, ['A'], Symbol('A'),
      new String('A'), { toString: () => 'A' }
    ]

    test('non-strings as previous throw RangeError', () => {
      for (const val of nonStrings) {
        assert.throws(
          () => notchChange(val, 'A'),
          RangeError,
          `failed for ${typeof val === 'symbol' ? 'Symbol' : JSON.stringify(val)}`
        )
      }
    })

    test('non-strings as current throw RangeError', () => {
      for (const val of nonStrings) {
        assert.throws(
          () => notchChange('A', val),
          RangeError,
          `failed for ${typeof val === 'symbol' ? 'Symbol' : JSON.stringify(val)}`
        )
      }
    })

    test('missing arguments throw RangeError', () => {
      assert.throws(() => notchChange(), RangeError)
      assert.throws(() => notchChange('A'), RangeError)
    })
  })

  describe('AC-12: return value properties', () => {
    test('returns a number', () => {
      const result = notchChange('BBB+', 'BB+')
      assert.equal(typeof result, 'number')
    })

    test('return value is not a Promise', () => {
      const result = notchChange('BBB+', 'BB+')
      assert.equal(typeof result?.then, 'undefined')
    })

    test('deterministic: same input returns same value', () => {
      const result1 = notchChange('BBB+', 'BB+')
      const result2 = notchChange('BBB+', 'BB+')
      assert.equal(result1, result2)
    })
  })

  describe('test data from spec: valid pairs', () => {
    const validPairs = [
      ['BBB+', 'BB+', 3],
      ['BB+', 'BBB+', -3],
      ['A', 'A', 0],
      ['CCC-', 'CCC-', 0],
      ['AAA', 'AA+', 1],
      ['BBB-', 'BBB', -1],
      ['BBB-', 'BB+', 1],
      ['B-', 'CCC+', 1],
      ['AAA', 'CCC-', 18],
      ['CCC-', 'AAA', -18],
      ['  BBB+ ', 'BB+', 3],
      ['\tA-\n', 'A-', 0],
      [' AAA', 'AA+​', 1],
      ['BB+', ' BBB+\r\n', -3],
      ['bbb+', 'bb+', 3],
      ['Bb+', 'bBb+', -3],
      ['aaa', 'CCC-', 18],
      [' ccc- ', 'aAa', -18],
      ['a', 'A', 0]
    ]

    for (const [previous, current, expected] of validPairs) {
      test(`notchChange(${JSON.stringify(previous)}, ${JSON.stringify(current)}) === ${expected}`, () => {
        const result = notchChange(previous, current)
        assert.equal(result, expected)
      })
    }
  })
})

export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
])

export function notchChange(previous, current) {
  // Type check before trim (reject non-strings with RangeError, not TypeError)
  if (typeof previous !== 'string') {
    throw new RangeError('Invalid input: previous must be a string')
  }
  if (typeof current !== 'string') {
    throw new RangeError('Invalid input: current must be a string')
  }

  // Trim and normalize to uppercase
  const prevTrimmed = previous.trim().toUpperCase()
  const currTrimmed = current.trim().toUpperCase()

  // Look up indices in the scale
  const prevIdx = RATING_SCALE.indexOf(prevTrimmed)
  const currIdx = RATING_SCALE.indexOf(currTrimmed)

  // Throw RangeError if not found
  if (prevIdx === -1) {
    throw new RangeError('Invalid rating for previous')
  }
  if (currIdx === -1) {
    throw new RangeError('Invalid rating for current')
  }

  // Return the notch change: positive for downgrade, negative for upgrade
  // Direct subtraction naturally avoids -0
  return currIdx - prevIdx
}

