  test('AC-12: no console output in valid or throwing calls', () => {
    const stubs = {
      log: null,
      error: null,
      stdout: null,
      stderr: null
    }

    try {
      // Stub console methods
      stubs.log = console.log
      stubs.error = console.error
      stubs.stdout = process.stdout.write
      stubs.stderr = process.stderr.write

      let logCalls = 0
      let errorCalls = 0
      let stdoutCalls = 0
      let stderrCalls = 0

      console.log = () => { logCalls++ }
      console.error = () => { errorCalls++ }
      process.stdout.write = () => { stdoutCalls++; return true }
      process.stderr.write = () => { stderrCalls++; return true }

      // Valid calls
      notchChange('BBB+', 'BB+')
      notchChange('A', 'A')
      notchChange('AAA', 'CCC-')

      // Throwing calls
      assert.throws(() => notchChange('INVALID', 'A'), RangeError)
      assert.throws(() => notchChange('A', undefined), RangeError)
      assert.throws(() => notchChange('', 'A'), RangeError)

      // Assert no calls to console/stdout/stderr
      assert.equal(logCalls, 0, 'console.log should not be called')
      assert.equal(errorCalls, 0, 'console.error should not be called')
      assert.equal(stdoutCalls, 0, 'process.stdout.write should not be called')
      assert.equal(stderrCalls, 0, 'process.stderr.write should not be called')
    } finally {
      // Restore stubs
      console.log = stubs.log
      console.error = stubs.error
      process.stdout.write = stubs.stdout
      process.stderr.write = stubs.stderr
