@@ -0,0 +1,35 @@
+export const RATING_SCALE = Object.freeze([
+  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
+  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
+  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'
+])
+
+export function notchChange(previous, current) {
+  // Type check before trim (reject non-strings with RangeError, not TypeError)
+  if (typeof previous !== 'string') {
+    throw new RangeError('Invalid input: previous must be a string')
+  }
+  if (typeof current !== 'string') {
+    throw new RangeError('Invalid input: current must be a string')
+  }
+
+  // Trim and normalize to uppercase
+  const prevTrimmed = previous.trim().toUpperCase()
+  const currTrimmed = current.trim().toUpperCase()
+
+  // Look up indices in the scale
+  const prevIdx = RATING_SCALE.indexOf(prevTrimmed)
+  const currIdx = RATING_SCALE.indexOf(currTrimmed)
+
+  // Throw RangeError if not found
+  if (prevIdx === -1) {
+    throw new RangeError('Invalid rating for previous')
+  }
+  if (currIdx === -1) {
+    throw new RangeError('Invalid rating for current')
+  }
+
+  // Return the notch change: positive for downgrade, negative for upgrade
+  // Direct subtraction naturally avoids -0
+  return currIdx - prevIdx
+}
