+  }
+});
+
+test('AC-4: RATING_SCALE has the 19 C1 ratings, best first', () => {
+  assert.equal(RATING_SCALE.length, 19);
+  assert.deepEqual([...RATING_SCALE], EXPECTED_SCALE);
+  assert.equal(RATING_SCALE[0], 'AAA');
+  assert.equal(RATING_SCALE[18], 'CCC-');
+});
+
+test('AC-5: RATING_SCALE is frozen and mutation attempts throw TypeError', () => {
+  assert.equal(Object.isFrozen(RATING_SCALE), true);
