+  assert.deepEqual([...RATING_SCALE], EXPECTED_SCALE);
+  assert.equal(notchChange('BBB+', 'BB+'), 3);
+});
+
+test('AC-6: adjacent ratings differ by 1 and reversed by -1', () => {
+  for (let i = 0; i < 18; i++) {
+    assert.equal(notchChange(RATING_SCALE[i], RATING_SCALE[i + 1]), 1, `${RATING_SCALE[i]} -> ${RATING_SCALE[i + 1]}`);
+    assert.equal(notchChange(RATING_SCALE[i + 1], RATING_SCALE[i]), -1, `${RATING_SCALE[i + 1]} -> ${RATING_SCALE[i]}`);
+  }
+});
+
+test('AC-6: spot checks and extremes', () => {
+  assert.equal(notchChange('AAA', 'AA+'), 1);
+  assert.equal(notchChange('BBB', 'BBB-'), 1);
+  assert.equal(notchChange('BBB-', 'BBB'), -1);
+  assert.equal(notchChange('BBB-', 'BB+'), 1);
+  assert.equal(notchChange('B-', 'CCC+'), 1);
+  assert.equal(notchChange('AAA', 'CCC-'), 18);
+  assert.equal(notchChange('CCC-', 'AAA'), -18);
+});
+
+test('AC-6: full 19x19 matrix equals j - i (361 pairs)', () => {
+  let n = 0;
+  for (let i = 0; i < 19; i++) {
+    for (let j = 0; j < 19; j++) {
+      assert.equal(notchChange(EXPECTED_SCALE[i], EXPECTED_SCALE[j]), j - i, `${EXPECTED_SCALE[i]} -> ${EXPECTED_SCALE[j]}`);
+      n++;
+    }
+  }
+  assert.equal(n, 361);
+});
+
+test('AC-7: surrounding whitespace is trimmed', () => {
