+});
+
+const UNKNOWN = ['D', 'CC', 'C', 'SD', 'NR', 'WD', 'AAA+', 'CCC--', 'BBB +', 'BBB+.', 'A−', 'Baa1'];
+const BLANK = ['', '   ', '\t\n', ' '];
+const NON_STRINGS = [
+  ['undefined', undefined],
+  ['null', null],
