  assertRangeErrorBothPositions('full-width A', 'Ａ');
});

test('AC-10: empty and whitespace-only strings throw RangeError in either position (8 calls)', () => {
  for (const v of BLANK) assertRangeErrorBothPositions(JSON.stringify(v), v);
});

test('AC-11: non-strings throw RangeError (never TypeError) in either position (20 calls)', () => {
  for (const [label, v] of NON_STRINGS) {
    for (const call of [() => notchChange(v, 'A'), () => notchChange('A', v)]) {
      let err;
      try { call(); } catch (e) { err = e; }
      assert.ok(err instanceof RangeError, `${label}: expected RangeError, got ${err && err.constructor.name}`);
      assert.ok(!(err instanceof TypeError), `${label}: must not be TypeError`);
    }
  }
});

test('AC-11: missing arguments throw RangeError', () => {
  assert.throws(() => notchChange(), RangeError);
  assert.throws(() => notchChange('A'), RangeError);
});

test('AC-11: both arguments invalid still throws RangeError', () => {
  assert.throws(() => notchChange('D', null), RangeError);
  assert.throws(() => notchChange(null, 'D'), RangeError);
});

test('AC-12: synchronous number result, deterministic', () => {
  const r = notchChange('BBB+', 'BB+');
  assert.equal(typeof r, 'number');
  assert.equal(typeof r?.then, 'undefined');
  assert.equal(notchChange('BBB+', 'BB+'), r);
  assert.equal(notchChange('BBB+', 'BB+'), 3);
});

test('AC-12: writes nothing to console or stdout/stderr, valid or throwing', () => {
  const targets = [
    [console, 'log'],
    [console, 'error'],
    [process.stdout, 'write'],
    [process.stderr, 'write'],
  ];
  const originals = targets.map(([o, k]) => o[k]);
  let calls = 0;
  targets.forEach(([o, k]) => { o[k] = () => { calls++; return true; }; });
  try {
    notchChange('BBB+', 'BB+');
    notchChange(' a ', 'CCC-');
    assert.throws(() => notchChange('D', 'A'), RangeError);
    assert.throws(() => notchChange(null, 'A'), RangeError);
    assert.throws(() => notchChange(), RangeError);
  } finally {
    targets.forEach(([o, k], n) => { o[k] = originals[n]; });
  }
  assert.equal(calls, 0);
});

test('AC-12: src/ratings/notch.mjs has no import statements', () => {
  const src = readFileSync(new URL('../../../src/ratings/notch.mjs', import.meta.url), 'utf8');
  assert.doesNotMatch(src, /^\s*import\b/m);
});

test('AC-12: package.json declares no dependencies or devDependencies', () => {
  const pkg = JSON.parse(readFileSync(new URL('../../../package.json', import.meta.url), 'utf8'));
  assert.equal('dependencies' in pkg, false);
  assert.equal('devDependencies' in pkg, false);
});

// The child run executes this file again; QA_AC13_CHILD stops it from recursing.
test('AC-13: node --test at the repo root exits 0 and includes the notch unit and integration tests', { skip: process.env.QA_AC13_CHILD === '1' && 'nested run' }, () => {
  const env = { ...process.env, QA_AC13_CHILD: '1' };
  delete env.NODE_TEST_CONTEXT;
  const run = (args) => {
    const res = spawnSync(process.execPath, ['--test', '--test-reporter=tap', ...args], { cwd: ROOT, env, encoding: 'utf8' });
    const out = `${res.stdout}\n${res.stderr}`;
    const num = (name) => Number((out.match(new RegExp(`^# ${name} (\\d+)`, 'm')) || [])[1]);
    return { status: res.status, out, pass: num('pass'), fail: num('fail'), tests: num('tests') };
  };
  const root = run([]);
  assert.equal(root.status, 0, root.out);
  assert.equal(root.fail, 0, root.out);
  // the unit file alone, to prove its tests are part of the root run
  const unit = run(['test/ratings/notch.test.mjs']);
  assert.equal(unit.status, 0, unit.out);
  assert.ok(unit.tests > 0, 'unit test file ran no tests');
  // the integration tests of this directory are part of the root run
  assert.match(root.out, /^\s*(not )?ok \d+ - AC-1: notchChange\(BBB\+, BB\+\) is the integer 3/m);
  assert.match(root.out, /^\s*(not )?ok \d+ - AC-12: package\.json declares no dependencies/m);
  assert.ok(root.tests >= unit.tests + 20, `root run has ${root.tests} tests, unit file alone ${unit.tests}`);
});
